from __future__ import annotations

from pydantic import Field
from typing_extensions import NotRequired, TypedDict

from ..core import UNSET, Optional, SdkBaseModel
from .decision import Decision, DecisionDict
from .task_list import TaskList, TaskListDict


class RespondDecisionTaskCompletedInput(SdkBaseModel):
    task_token: str = Field(alias="taskToken")
    """The taskToken from the DecisionTask. taskToken is generated by the service and should be treated as an opaque
    value. If the task is passed to another process, its taskToken must also be passed. This enables it to provide its
    progress and respond with results."""

    decisions: Optional[list[Decision]] = UNSET
    """The list of decisions (possibly empty) made by the decider while processing this decision task. See the docs for
    the Decision structure for details."""

    execution_context: Optional[str] = Field(default=UNSET, alias="executionContext")
    """User defined context to add to workflow execution."""

    task_list: Optional[TaskList] = Field(default=UNSET, alias="taskList")
    task_list_schedule_to_start_timeout: Optional[str] = Field(default=UNSET, alias="taskListScheduleToStartTimeout")
    """Specifies a timeout (in seconds) for the task list override. When this parameter is missing, the task list
    override is permanent. This parameter makes it possible to temporarily override the task list. If a decision task
    scheduled on the override task list is not started within the timeout, the decision task will time out. Amazon SWF
    will revert the override and schedule a new decision task to the original task list. If a decision task scheduled on
    the override task list is started within the timeout, but not completed within the start-to-close timeout, Amazon
    SWF will also revert the override"""


class RespondDecisionTaskCompletedInputDict(TypedDict):
    task_token: str
    decisions: NotRequired[list[DecisionDict]]
    execution_context: NotRequired[str]
    task_list: NotRequired[TaskListDict]
    task_list_schedule_to_start_timeout: NotRequired[str]
